/**
 * Super Eagles Telemetry & Smartwatch File Ingestion Engine
 * Parses standard .GPX and .TCX activity files generated by Garmin, Strava, Coros, Polar, and Apple Watch.
 */

export interface TrackPoint {
  lat: number;
  lon: number;
  elevation?: number;
  time?: Date;
  heartRate?: number;
}

export interface ParsedTelemetry {
  fileName: string;
  activityName: string;
  startTime: Date;
  endTime: Date;
  totalDistanceKm: number;
  totalDurationSeconds: number;
  averagePaceSecondsPerKm: number;
  elevationGainMeters: number;
  elevationLossMeters: number;
  averageHeartRate?: number;
  maxHeartRate?: number;
  minHeartRate?: number;
  trackPointsCount: number;
  suggestedWorkoutType: "LONG_RUN" | "TEMPO" | "INTERVALS" | "EASY" | "RECOVERY" | "WALK" | "TIME_TRIAL";
  isWalkingDiscipline: boolean;
}

/**
 * Calculates great-circle distance between two coordinates using the Haversine formula (in meters).
 */
function haversineDistanceMeters(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371000; // Earth's radius in meters
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

/**
 * Parses raw GPX XML string into structured athletic telemetry.
 */
export function parseGpxString(xmlContent: string, fileName: string = "activity.gpx"): ParsedTelemetry {
  if (!xmlContent || typeof xmlContent !== "string") {
    throw new Error("Invalid GPX file: content is empty.");
  }

  // Parse XML using browser DOMParser or basic regex fallback
  let doc: Document | null = null;
  if (typeof window !== "undefined" && window.DOMParser) {
    const parser = new DOMParser();
    doc = parser.parseFromString(xmlContent, "application/xml");
    const parserError = doc.querySelector("parsererror");
    if (parserError) {
      throw new Error("Corrupt GPX XML structure.");
    }
  }

  const trackPoints: TrackPoint[] = [];
  let activityName = "Smartwatch Workout";

  if (doc) {
    const nameEl = doc.querySelector("trk > name, metadata > name");
    if (nameEl?.textContent) {
      activityName = nameEl.textContent.trim();
    }

    const trkptEls = doc.querySelectorAll("trkpt");
    trkptEls.forEach((el) => {
      const lat = parseFloat(el.getAttribute("lat") || "0");
      const lon = parseFloat(el.getAttribute("lon") || "0");
      const eleEl = el.querySelector("ele");
      const timeEl = el.querySelector("time");
      const hrEl = el.querySelector("hr, gpxtpx\\:hr, ns3\\:hr, [name='heart_rate']");

      trackPoints.push({
        lat,
        lon,
        elevation: eleEl?.textContent ? parseFloat(eleEl.textContent) : undefined,
        time: timeEl?.textContent ? new Date(timeEl.textContent) : undefined,
        heartRate: hrEl?.textContent ? parseInt(hrEl.textContent, 10) : undefined,
      });
    });
  } else {
    // Regex fallback for server-side testing without browser DOMParser
    const nameMatch = xmlContent.match(/<name>(.*?)<\/name>/i);
    if (nameMatch) activityName = nameMatch[1];

    const trkptRegex = /<trkpt\s+lat="([^"]+)"\s+lon="([^"]+)"[^>]*>([\s\S]*?)<\/trkpt>/gi;
    let match;
    while ((match = trkptRegex.exec(xmlContent)) !== null) {
      const lat = parseFloat(match[1]);
      const lon = parseFloat(match[2]);
      const inner = match[3];

      const eleMatch = inner.match(/<ele>([^<]+)<\/ele>/i);
      const timeMatch = inner.match(/<time>([^<]+)<\/time>/i);
      const hrMatch = inner.match(/<(?:\w+:)?hr>([^<]+)<\/(?:\w+:)?hr>/i);

      trackPoints.push({
        lat,
        lon,
        elevation: eleMatch ? parseFloat(eleMatch[1]) : undefined,
        time: timeMatch ? new Date(timeMatch[1]) : undefined,
        heartRate: hrMatch ? parseInt(hrMatch[1], 10) : undefined,
      });
    }
  }

  if (trackPoints.length === 0) {
    throw new Error("No GPS track points found in GPX file.");
  }

  // Calculate cumulative distance and elevation changes
  let totalDistanceMeters = 0;
  let elevationGainMeters = 0;
  let elevationLossMeters = 0;
  const hrValues: number[] = [];

  for (let i = 0; i < trackPoints.length; i++) {
    const pt = trackPoints[i];
    if (pt.heartRate && !isNaN(pt.heartRate) && pt.heartRate > 30 && pt.heartRate < 230) {
      hrValues.push(pt.heartRate);
    }

    if (i > 0) {
      const prev = trackPoints[i - 1];
      const dist = haversineDistanceMeters(prev.lat, prev.lon, pt.lat, pt.lon);
      // Filter out GPS jump spikes (> 50 m/s or 180 km/h)
      if (dist < 500) {
        totalDistanceMeters += dist;
      }

      if (pt.elevation !== undefined && prev.elevation !== undefined) {
        const dEle = pt.elevation - prev.elevation;
        if (dEle > 0) {
          elevationGainMeters += dEle;
        } else {
          elevationLossMeters += Math.abs(dEle);
        }
      }
    }
  }

  const firstTime = trackPoints[0]?.time || new Date();
  const lastTime = trackPoints[trackPoints.length - 1]?.time || new Date(firstTime.getTime() + 3600000);
  let totalDurationSeconds = Math.max(1, Math.round((lastTime.getTime() - firstTime.getTime()) / 1000));

  // If GPS timestamps were missing or corrupted, calculate an estimated duration based on normal pace
  if (totalDurationSeconds <= 1 && totalDistanceMeters > 0) {
    totalDurationSeconds = Math.round((totalDistanceMeters / 1000) * 330); // default 5:30/km
  }

  const totalDistanceKm = Number((totalDistanceMeters / 1000).toFixed(2));
  const averagePaceSecondsPerKm =
    totalDistanceKm > 0 ? Math.round(totalDurationSeconds / totalDistanceKm) : 0;

  // Compute heart rate analytics if present
  let averageHeartRate: number | undefined;
  let maxHeartRate: number | undefined;
  let minHeartRate: number | undefined;
  if (hrValues.length > 0) {
    const hrSum = hrValues.reduce((acc, v) => acc + v, 0);
    averageHeartRate = Math.round(hrSum / hrValues.length);
    maxHeartRate = Math.max(...hrValues);
    minHeartRate = Math.min(...hrValues);
  }

  // Determine workout type and discipline
  const isWalkingDiscipline = averagePaceSecondsPerKm >= 510; // >= 8:30 min/km -> Walking
  let suggestedWorkoutType: ParsedTelemetry["suggestedWorkoutType"] = "EASY";

  if (isWalkingDiscipline) {
    suggestedWorkoutType = "WALK";
  } else if (totalDistanceKm >= 21.1) {
    suggestedWorkoutType = "LONG_RUN";
  } else if (averagePaceSecondsPerKm <= 260 && totalDistanceKm >= 5) {
    suggestedWorkoutType = "TEMPO"; // Fast sub 4:20/km tempo
  } else if (totalDistanceKm <= 6.0) {
    suggestedWorkoutType = "RECOVERY";
  }

  return {
    fileName,
    activityName: activityName || "Smartwatch GPS Session",
    startTime: firstTime,
    endTime: lastTime,
    totalDistanceKm,
    totalDurationSeconds,
    averagePaceSecondsPerKm,
    elevationGainMeters: Math.round(elevationGainMeters),
    elevationLossMeters: Math.round(elevationLossMeters),
    averageHeartRate,
    maxHeartRate,
    minHeartRate,
    trackPointsCount: trackPoints.length,
    suggestedWorkoutType,
    isWalkingDiscipline,
  };
}

